</script>
<script>
// --- Embedded docs ---
const DOCS = DOCS_PLACEHOLDER;

// --- Init ---
hljs.configure({ ignoreUnescapedHTML: true });
const docs = DOCS;
const nav = document.getElementById('nav');
const content = document.getElementById('content');
const searchInput = document.getElementById('searchInput');
const topBtn = document.getElementById('top-btn');

// Configure marked
marked.setOptions({
  gfm: true,
  breaks: false,
});

// Generate heading IDs using auto-increment
function addHeadingIds(container) {
  let counter = 0;
  container.querySelectorAll('h1,h2,h3,h4,h5,h6').forEach(h => {
    if (!h.id) {
      h.id = 'heading-' + (++counter);
    }
  });
}

// Build nav
const entries = [
  ["CSharp_Tutorial.md",     "📘 C# 语言教学"],
  ["Code_Tutorial.md",       "📗 代码逐文件教学"],
  ["PInvoke_Guide.md",       "📙 P/Invoke 编程指南"],
  ["CLI_Reference.md",       "📕 CLI 命令参考"],
  ["UI_Development_Guide.md","📒 UI 开发指南"],
];

let currentKey = entries[0][0];

entries.forEach(([key, label]) => {
  const a = document.createElement('a');
  a.href = '#';
  a.textContent = label;
  a.dataset.key = key;
  if (key === currentKey) a.classList.add('active');
  a.addEventListener('click', e => { e.preventDefault(); showDoc(key); });
  nav.appendChild(a);
});

function showDoc(key) {
  currentKey = key;
  document.querySelectorAll('#nav a').forEach(a => {
    a.classList.toggle('active', a.dataset.key === key);
  });
  const md = docs[key] || '# Not found';
  content.innerHTML = marked.parse(md);
  addHeadingIds(content);
  window.scrollTo({ top: 0 });
  content.querySelectorAll('pre code').forEach(el => hljs.highlightElement(el));
}

// Handle anchor clicks within content (internal TOC links)
document.addEventListener('click', e => {
  const a = e.target.closest('#content a[href^="#"]');
  if (!a) return;
  e.preventDefault();
  const targetId = decodeURIComponent(a.getAttribute('href').slice(1));
  const target = document.getElementById(targetId);
  if (target) {
    const offset = 20; // padding from top
    const y = target.getBoundingClientRect().top + window.scrollY - offset;
    window.scrollTo({ top: y, behavior: 'smooth' });
    history.replaceState(null, '', '#' + targetId);
  }
});

// Search
searchInput.addEventListener('input', () => {
  const q = searchInput.value.trim().toLowerCase();
  document.querySelectorAll('#nav a').forEach(a => {
    const key = a.dataset.key;
    const md = (docs[key] || '').toLowerCase();
    const label = a.textContent.toLowerCase();
    a.style.display = (!q || label.includes(q) || md.includes(q)) ? '' : 'none';
  });
});

// Back to top button
window.addEventListener('scroll', () => {
  topBtn.style.display = window.scrollY > 400 ? 'block' : 'none';
});

// Initial render
showDoc(currentKey);

// Handle hash on page load
if (location.hash) {
  const targetId = decodeURIComponent(location.hash.slice(1));
  const target = document.getElementById(targetId);
  if (target) {
    setTimeout(() => {
      const offset = 20;
      const y = target.getBoundingClientRect().top + window.scrollY - offset;
      window.scrollTo({ top: y });
    }, 100);
  }
}
</script>
</body>
</html>
